declarations.header:
theorem actual_program_register_support (N : RootedBinary V E X) {sample : Root → X}
    (r : PositivePairRates E) (ops : List (ProgramStep N)) (s : Code N sample) {d : Code N sample}
    (hd : d ∈ (sourceProgram N r ops s).support) : (state d).register = (state s).register

theorem erasePrivateCode_genealogy (N : RootedBinary V E X) {sample : Copy → X}
    (P : Finset V) (s : Code N sample) :
    (state (erasePrivateCode N P s)).genealogy = (state s).genealogy
